"""Converters between human-readable and machine-friendly representations."""

import math

__all__ = [
    "convert_size_bytes_to_string",
    "convert_size_string_to_bytes",
]

_SIZE_UNITS = ("B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB")


def convert_size_bytes_to_string(size_bytes: int) -> str:
    """Convert a size in bytes to a human-readable string (e.g. 1536 -> '1.5 KB')."""
    if size_bytes < 0:
        raise ValueError(f"size_bytes must be >= 0, got {size_bytes}")
    if size_bytes == 0:
        return "0B"
    i = min(int(math.floor(math.log(size_bytes, 1024))), len(_SIZE_UNITS) - 1)
    s = round(size_bytes / 1024**i, 2)
    return f"{s} {_SIZE_UNITS[i]}"


def convert_size_string_to_bytes(size: str) -> int:
    """Convert a human-readable size string (e.g. '2.5 MB') to bytes.

    The unit is optional and case-insensitive, defaulting to bytes.
    Raises ValueError on malformed input.
    """
    if not isinstance(size, str):
        raise ValueError(f"size must be a string, got {type(size).__name__}")
    parts = size.strip().split()
    if not 1 <= len(parts) <= 2:
        raise ValueError(f"malformed size string: {size!r}")
    number_part = parts[0]
    unit_part = parts[1].upper() if len(parts) == 2 else "B"
    if unit_part not in _SIZE_UNITS:
        raise ValueError(f"unknown size unit in {size!r}")
    try:
        value = float(number_part)
    except ValueError:
        raise ValueError(f"malformed size string: {size!r}") from None
    if value < 0:
        raise ValueError(f"size must be >= 0, got {size!r}")
    return int(value * 1024 ** _SIZE_UNITS.index(unit_part))

