"""Read and write file-system permission bits."""

import os
import stat

__all__ = [
    "get_permissions",
    "set_permissions",
]


def get_permissions(path: str | os.PathLike) -> int:
    """Return the permission bits of the file at *path* (e.g. 0o755)."""
    return stat.S_IMODE(os.stat(path).st_mode)


def set_permissions(path: str | os.PathLike, permissions: int | str) -> None:
    """Set the permission bits of the file at *path*.

    *permissions* may be an int (e.g. 0o755) or a string of octal digits
    (e.g. '755'). Raises ValueError on a malformed octal string.
    """
    if isinstance(permissions, str):
        mode = int(permissions, 8)
    elif isinstance(permissions, int):
        mode = permissions
    else:
        raise TypeError(
            f"permissions must be an int or an octal string, got {type(permissions).__name__}"
        )
    os.chmod(path, mode)

