"""File-system path manipulation utilities."""

from __future__ import annotations

import os
from typing import Callable, Union

PathLike = Union[str, os.PathLike]


def get_path(
    path: PathLike,
    *,
    expanduser: bool = True,
    absolute: bool = False,
) -> str:
    """Return a normalized path, optionally expanding '~' and making it absolute."""
    path = os.fspath(path)
    if expanduser:
        path = os.path.expanduser(path)
    path = os.path.normpath(path)
    if absolute:
        path = os.path.abspath(path)
    return path


def join_path(path: PathLike, *paths: PathLike) -> str:
    """Join all path parts and normalize the result."""
    return os.path.normpath(os.path.join(os.fspath(path), *map(os.fspath, paths)))


def split_path(path: PathLike) -> list[str]:
    """Split a path into all its components ('/a/b' -> ['/', 'a', 'b'])."""
    path = os.fspath(path)
    parts: list[str] = []
    while True:
        head, tail = os.path.split(path)
        if tail:
            parts.append(tail)
            path = head
        else:
            if head:
                parts.append(head)
            break
    parts.reverse()
    return parts


def split_filepath(path: PathLike) -> tuple[str, str]:
    """Split a path into (dirpath, filename); dirpath is '' when none."""
    dirpath, filename = os.path.split(os.fspath(path))
    return dirpath, filename


def split_filename(path: PathLike) -> tuple[str, str]:
    """Split the filename portion into (basename, extension); extension includes the dot."""
    _, filename = split_filepath(path)
    basename, extension = os.path.splitext(filename)
    return basename, extension


def get_filename(path: PathLike) -> str:
    """Return the final path component, including its extension."""
    return os.path.basename(os.fspath(path))


def get_file_basename(path: PathLike) -> str:
    """Return the filename without its extension."""
    basename, _ = split_filename(path)
    return basename


def get_file_extension(path: PathLike) -> str:
    """Return the filename extension including the leading dot, '' when none."""
    _, extension = split_filename(path)
    return extension


def get_parent_dir(path: PathLike, levels: int = 1) -> str:
    """Return the parent directory, going up `levels` directories."""
    if levels < 1:
        raise ValueError(f"levels must be >= 1, got {levels}")
    path = os.fspath(path)
    for _ in range(levels):
        path = os.path.dirname(path)
    return path


def join_filename(basename: PathLike, extension: str) -> str:
    """Join a basename and an extension with a dot, adding the dot if missing."""
    basename = os.fspath(basename)
    if extension and not extension.startswith("."):
        extension = "." + extension
    return basename + extension


def join_filepath(dirpath: PathLike, filename: PathLike) -> str:
    """Join a directory path and a filename into a normalized path."""
    return join_path(dirpath, filename)


def transform_filepath(
    path: PathLike,
    func: Callable[[str], str],
) -> str:
    """Apply `func` to the filename portion of `path` and rejoin with its dirpath."""
    dirpath, filename = split_filepath(path)
    return join_filepath(dirpath, func(filename))

