"""Assertion-style and boolean checks for file-system paths."""

import os

from fsutil.exceptions import FSUtilError


def _fspath(path: str | os.PathLike) -> str:
    """Return *path* as a plain ``str``."""
    return os.fspath(path)


def exists(path: str | os.PathLike) -> bool:
    """Return True if *path* exists."""
    return os.path.exists(_fspath(path))


def assert_exists(path: str | os.PathLike) -> None:
    """Raise FSUtilError if *path* does not exist."""
    if not exists(path):
        raise FSUtilError(f"path does not exist: {_fspath(path)!r}")


def assert_not_exists(path: str | os.PathLike) -> None:
    """Raise FSUtilError if *path* exists."""
    if exists(path):
        raise FSUtilError(f"path already exists: {_fspath(path)!r}")


def is_file(path: str | os.PathLike) -> bool:
    """Return True if *path* is an existing regular file."""
    return os.path.isfile(_fspath(path))


def is_dir(path: str | os.PathLike) -> bool:
    """Return True if *path* is an existing directory."""
    return os.path.isdir(_fspath(path))


def assert_file(path: str | os.PathLike) -> None:
    """Raise FSUtilError if *path* is not an existing regular file."""
    if not is_file(path):
        raise FSUtilError(f"path is not a file: {_fspath(path)!r}")


def assert_dir(path: str | os.PathLike) -> None:
    """Raise FSUtilError if *path* is not an existing directory."""
    if not is_dir(path):
        raise FSUtilError(f"path is not a directory: {_fspath(path)!r}")


def assert_not_file(path: str | os.PathLike) -> None:
    """Raise FSUtilError if *path* is an existing regular file."""
    if is_file(path):
        raise FSUtilError(f"path is a file: {_fspath(path)!r}")


def assert_not_dir(path: str | os.PathLike) -> None:
    """Raise FSUtilError if *path* is an existing directory."""
    if is_dir(path):
        raise FSUtilError(f"path is a directory: {_fspath(path)!r}")


def is_empty(path: str | os.PathLike) -> bool:
    """Return True if *path* is an empty file or an empty directory.

    A file is empty when its size is 0 bytes; a directory is empty when it
    contains no entries. Raise FileNotFoundError if *path* does not exist.
    """
    path = _fspath(path)
    if not os.path.exists(path):
        raise FileNotFoundError(f"path does not exist: {path!r}")
    if os.path.isdir(path):
        return not os.listdir(path)
    return os.path.getsize(path) == 0


def is_empty_file(path: str | os.PathLike) -> bool:
    """Return True if *path* is a file with size 0; *path* must be a file."""
    path = _fspath(path)
    if not os.path.isfile(path):
        raise FileNotFoundError(f"path is not an existing file: {path!r}")
    return os.path.getsize(path) == 0


def is_empty_dir(path: str | os.PathLike) -> bool:
    """Return True if *path* is a directory with no entries; *path* must be a dir."""
    path = _fspath(path)
    if not os.path.isdir(path):
        raise FileNotFoundError(f"path is not an existing directory: {path!r}")
    return not os.listdir(path)

