"""File and directory information helpers (sizes, dates, hashes)."""

import datetime
import hashlib
import os

from fsutil.converters import convert_size_bytes_to_string

_DATETIME_FORMAT = "%Y-%m-%d %H:%M:%S"
_HASH_CHUNK_SIZE = 64 * 1024


def _fspath(path: str | os.PathLike) -> str:
    """Return *path* as a plain ``str``."""
    return os.fspath(path)


def get_file_size(path: str | os.PathLike) -> int:
    """Return the size of the file at *path* in bytes."""
    return os.path.getsize(_fspath(path))


def get_file_size_formatted(path: str | os.PathLike) -> str:
    """Return the size of the file at *path* as a human-readable string."""
    return convert_size_bytes_to_string(get_file_size(path))


def get_dir_size(path: str | os.PathLike) -> int:
    """Return the total size in bytes of all files contained in *path*, recursively."""
    path = _fspath(path)
    total = 0
    for root, _dirs, files in os.walk(path):
        for name in files:
            filepath = os.path.join(root, name)
            if not os.path.islink(filepath):
                total += os.path.getsize(filepath)
    return total


def get_dir_size_formatted(path: str | os.PathLike) -> str:
    """Return the total size of *path* as a human-readable string."""
    return convert_size_bytes_to_string(get_dir_size(path))


def get_file_creation_date(path: str | os.PathLike) -> datetime.datetime:
    """Return the creation date (st_ctime) of the file at *path*."""
    return datetime.datetime.fromtimestamp(os.path.getctime(_fspath(path)))


def get_file_creation_date_formatted(
    path: str | os.PathLike, format: str = _DATETIME_FORMAT
) -> str:
    """Return the creation date of the file at *path* formatted with *format*."""
    return get_file_creation_date(path).strftime(format)


def get_file_last_modified_date(path: str | os.PathLike) -> datetime.datetime:
    """Return the last modified date (st_mtime) of the file at *path*."""
    return datetime.datetime.fromtimestamp(os.path.getmtime(_fspath(path)))


def get_file_last_modified_date_formatted(
    path: str | os.PathLike, format: str = _DATETIME_FORMAT
) -> str:
    """Return the last modified date of the file at *path* formatted with *format*."""
    return get_file_last_modified_date(path).strftime(format)


def get_dir_creation_date(path: str | os.PathLike) -> datetime.datetime:
    """Return the creation date (st_ctime) of the directory at *path*."""
    return datetime.datetime.fromtimestamp(os.path.getctime(_fspath(path)))


def get_dir_creation_date_formatted(
    path: str | os.PathLike, format: str = _DATETIME_FORMAT
) -> str:
    """Return the creation date of the directory at *path* formatted with *format*."""
    return get_dir_creation_date(path).strftime(format)


def get_dir_last_modified_date(path: str | os.PathLike) -> datetime.datetime:
    """Return the last modified date (st_mtime) of the directory at *path*."""
    return datetime.datetime.fromtimestamp(os.path.getmtime(_fspath(path)))


def get_dir_last_modified_date_formatted(
    path: str | os.PathLike, format: str = _DATETIME_FORMAT
) -> str:
    """Return the last modified date of the directory at *path* formatted with *format*."""
    return get_dir_last_modified_date(path).strftime(format)


def _new_hasher(func: str) -> "hashlib._Hash":
    """Return a new hashlib hasher for algorithm *func*; raise ValueError if unknown."""
    try:
        return hashlib.new(func)
    except (ValueError, TypeError) as exc:
        raise ValueError(f"unknown hash algorithm: {func!r}") from exc


def get_file_hash(path: str | os.PathLike, func: str = "md5") -> str:
    """Return the hexdigest of the file at *path* using hashlib algorithm *func*.

    The file is read in 64KB chunks. Raise ValueError for an unknown algorithm.
    """
    hasher = _new_hasher(func)
    with open(_fspath(path), "rb") as file:
        while True:
            chunk = file.read(_HASH_CHUNK_SIZE)
            if not chunk:
                break
            hasher.update(chunk)
    return hasher.hexdigest()


def get_dir_hash(path: str | os.PathLike, func: str = "md5") -> str:
    """Return a hexdigest computed over the sorted (relative path, file hash)
    pairs of all files contained in *path*, recursively."""
    path = _fspath(path)
    entries = []
    for root, _dirs, files in os.walk(path):
        for name in files:
            filepath = os.path.join(root, name)
            if not os.path.isfile(filepath) or os.path.islink(filepath):
                continue
            relpath = os.path.relpath(filepath, path)
            entries.append((relpath, get_file_hash(filepath, func=func)))
    entries.sort()
    hasher = _new_hasher(func)
    for relpath, file_hash in entries:
        hasher.update(relpath.encode("utf-8"))
        hasher.update(file_hash.encode("utf-8"))
    return hasher.hexdigest()

