def _new_hasher(func: str) -> "hashlib._Hash":
    """Return a new hashlib hasher for algorithm *func*; raise ValueError if unknown."""
    try:
        return hashlib.new(func)
    except (ValueError, TypeError) as exc:
        raise ValueError(f"unknown hash algorithm: {func!r}") from exc


def get_file_hash(path: str | os.PathLike, func: str = "md5") -> str:
    """Return the hexdigest of the file at *path* using hashlib algorithm *func*.

    The file is read in 64KB chunks. Raise ValueError for an unknown algorithm.
    """
    hasher = _new_hasher(func)
    with open(_fspath(path), "rb") as file:
        while True:
            chunk = file.read(_HASH_CHUNK_SIZE)
            if not chunk:
                break
            hasher.update(chunk)
    return hasher.hexdigest()


def get_dir_hash(path: str | os.PathLike, func: str = "md5") -> str:
    """Return a hexdigest computed over the sorted (relative path, file hash)
    pairs of all files contained in *path*, recursively."""
    path = _fspath(path)
    entries = []
    for root, _dirs, files in os.walk(path):
        for name in files:
            filepath = os.path.join(root, name)
            if not os.path.isfile(filepath) or os.path.islink(filepath):
                continue
            relpath = os.path.relpath(filepath, path)
            entries.append((relpath, get_file_hash(filepath, func=func)))
    entries.sort()
    hasher = _new_hasher(func)
    for relpath, file_hash in entries:
        hasher.update(relpath.encode("utf-8"))
        hasher.update(file_hash.encode("utf-8"))
    return hasher.hexdigest()

